import{z as s,x as h,o as t,c as m,q as l,j as E,D as e,d as r,s as o,S as A,b as i}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"光学扩展量与远心","description":"","frontmatter":{"title":"光学扩展量与远心","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/etendue-telecentricity.md","filePath":"litho/etendue-telecentricity.md","lastUpdated":1791413859000}'),p={name:"litho/etendue-telecentricity.md"};function d(B,a,c,u,D,f){const n=h("Mermaid");return t(),m("div",null,[a[2]||(a[2]=l('<h1 id="光学扩展量与远心" tabindex="-1">光学扩展量与远心 <a class="header-anchor" href="#光学扩展量与远心" aria-label="Permalink to &quot;光学扩展量与远心&quot;">​</a></h1><div class="epigraph"><p>数值孔径给出能进镜头的最大张角；光学扩展量把面积与立体角锁在一起，远心则要求主光线不随离焦改倍率。</p><footer>—— 据 Born &amp; Wolf 对光学不变式 / 扩展量的讨论，以及 Levinson 对投影光刻远心的产线表述整理</footer></div><p><a href="/litho/lens-na">上一课</a>把投影物镜收成 \\(\\mathrm{NA}=n\\sin\\theta\\)，光瞳是频率轴上的硬截止。缺口是：\\(\\mathrm{NA}\\) 只回答「斜到什么程度还进得去」，不回答「有多少光能被送进这个锥」，也不回答「离焦时像会不会横向溜走」。本课补两个几何量：光学扩展量（etendue）与远心。照明如何填充这个光瞳，留给<a href="/litho/partial-coherence">部分相干</a>。仍不写产线 CD 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扫描机的晶圆面照度受光源亮度与扩展量限制。扩展量（拉格朗日不变量的积分形式）在无损耗系统里守恒：物方 \\(n^2 A \\Omega\\) 与像方相等。把投影 \\(\\mathrm{NA}\\) 做大，同一视场能接受的立体角变大，但光源必须提供匹配的扩展量，否则光瞳填不满，throughput 上不去；源的扩展量比镜头能吃的更大，多出来的光也进不去，只能丢掉。</p><p><span class="marginnote">直觉类比：扩展量像高速公路的总通行能力——车道数（面积）乘上限速下的车流（立体角）。镜头只是换匝道布局，改不了总容量；想塞进超过容量的车流，结果只能是堵在闸口（光瞳填不满）或干脆不许上路（多出来的光被丢掉）。</span></p><p>远心是另一件几何事。像方远心意味着主光线平行于光轴：离焦改变的是模糊，不改变倍率。残余远心误差会让套刻和 CD 随焦面一起漂。缺口因此是在 \\(\\mathrm{NA}\\) 之后把能量通道与轴向几何钉住，而不是开始谈 \\(k_1\\)。</p><h3 id="扩展量不是-na-的别名" tabindex="-1">扩展量不是 NA 的别名 <a class="header-anchor" href="#扩展量不是-na-的别名" aria-label="Permalink to &quot;扩展量不是 NA 的别名&quot;">​</a></h3><p>\\(\\mathrm{NA}\\) 是边缘光线角；扩展量还要乘发光面积（及 \\(n^2\\)）。同一 \\(\\mathrm{NA}\\)，狭缝变宽，扩展量变大，光源更难喂饱。准分子激光扩展量很小，照明可以几乎任意整形；放电或激光等离子体的扩展量更大，收集镜与中间焦点必须先做匹配。本课只给守恒接口，不写某代机台的瓦数。</p><p><span class="marginnote">数字实例：同一 \\(\\mathrm{NA}=0.33\\)，视场半径加倍则面积变 4 倍，扩展量 \\(n^2A\\Omega\\) 随之变 4 倍。「能容纳多大的张角」与「能喂进多少能量」是两个独立问题，扩展量量的是后者。</span></p><p><span class="marginnote">合同上的 \\(\\mathrm{NA}\\) 仍指晶圆侧。扩展量匹配发生在照明与投影之间：填不满是 \\(\\sigma\\) 上不去，喂过了是光源功率浪费。后面的课才把填充比叫做 \\(\\sigma\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>圆形、均匀填充的近似下，扩展量随 \\((n\\sin\\theta\\cdot r)^2\\) 涨，其中 \\(r\\) 是光瞳或视场相关半径，视约定。设计照明时先看投影能接受的最大扩展量，再决定源与积分器怎么填。守恒的是相空间体积，不是「镜头口径毫米数」：同样口径，工作距不同，\\(\\theta\\) 不同，扩展量不同——这与上一课「口径不是 \\(\\mathrm{NA}\\)」是同一几何。</p><p>远心：光瞳（出瞳）放到无穷远，主光线与轴平行。物方、像方可以分别远心。晶圆侧远心是套刻通过焦点仍稳的前提；掩模侧若有意留下主光线角（反射式 EUV 的斜入射），那是后课膜系与阴影的缺口，本课只要求：像方主光线一斜，离焦就产生倍率误差。</p><h3 id="远心误差是轴向预算的横向泄漏" tabindex="-1">远心误差是轴向预算的横向泄漏 <a class="header-anchor" href="#远心误差是轴向预算的横向泄漏" aria-label="Permalink to &quot;远心误差是轴向预算的横向泄漏&quot;">​</a></h3><p>调焦可以把平均面放回最佳焦面，但场内若远心随狭缝位置变，不同位置的主光线斜率不同，同一 \\(\\Delta z\\) 造成不同的 \\(\\Delta x\\)。这表现为通过焦点的套刻扇形或 CD 不对称，不是「\\(\\mathrm{NA}\\) 不够」。度量上要声明是狭缝中心还是边缘。</p><p><span class="marginnote">常见误区：调焦救不了远心误差。调焦只把平均面放回最佳焦面；场内主光线斜率若随狭缝位置变，同一离焦量在不同位置横移不同，表现为通过焦点的套刻扇形——新手常误判成对准或工件台问题，其实在镜头的轴向几何里。</span></p><p><span class="marginnote">不要把远心和焦深公式混成一个数。焦深问的是对比度还够不够；远心问的是糊斑的中心有没有横向搬家。两者都随 \\(\\mathrm{NA}\\) 变敏感，机制不同。</span></p>',18)),(t(),E(A,null,{default:e(()=>[o(n,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22%E6%8A%95%E5%BD%B1%20NA%22%5D%20--%3E%20ET%5B%22%E6%89%A9%E5%B1%95%E9%87%8F%20n%C2%B2A%CE%A9%22%5D%0A%20%20SRC%5B%22%E5%85%89%E6%BA%90%E4%BA%AE%E5%BA%A6%22%5D%20--%3E%20ET%0A%20%20ET%20--%3E%20TH%5B%22%E6%99%B6%E5%9C%86%E9%9D%A2%E9%80%9A%E9%87%8F%22%5D%0A%20%20NA%20--%3E%20TC%5B%22%E5%83%8F%E6%96%B9%E8%BF%9C%E5%BF%83%22%5D%0A%20%20TC%20--%3E%20MAG%5B%22%E7%A6%BB%E7%84%A6%E4%B8%8D%E6%94%B9%E5%80%8D%E7%8E%87%22%5D%0A%20%20TC%20--%3E%20ERR%5B%22%E6%AE%8B%E4%BD%99%E6%96%9C%E7%8E%87%20%E2%86%92%20%E5%A5%97%E5%88%BB%E9%9A%8F%E7%84%A6%E6%BC%82%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[r("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"相空间里，每条光线占一小格。镜头可以把格子从「大面积、小张角」换成「小面积、大张角」，格子总数（扩展量）不变。浸没提高像方 \\(n\\)，同样 \\(\\theta\\) 下扩展量与 \\(\\mathrm{NA}\\) 一起涨，光源与照明必须重新匹配——这是浸没课要付的能量账，本课先把账本立上。",-1)),(t(),E(A,null,{default:e(()=>[o(n,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20LR%0A%20%20O%5B%22%E7%89%A9%E6%96%B9%EF%BC%9A%E5%A4%A7%E9%9D%A2%E7%A7%AF%20%C3%97%20%E5%B0%8F%E5%BC%A0%E8%A7%92%22%5D%20--%3E%20L%5B%22%E6%97%A0%E6%8D%9F%E9%95%9C%E5%A4%B4%E9%87%8D%E6%8E%92%E7%9B%B8%E7%A9%BA%E9%97%B4%E6%A0%BC%E5%AD%90%22%5D%0A%20%20L%20--%3E%20I%5B%22%E5%83%8F%E6%96%B9%EF%BC%9A%E5%B0%8F%E9%9D%A2%E7%A7%AF%20%C3%97%20%E5%A4%A7%E5%BC%A0%E8%A7%92%22%5D%0A%20%20O%20--%3E%20G%5B%22%E6%A0%BC%E5%AD%90%E6%80%BB%E6%95%B0%20n%C2%B2A%CE%A9%20%E5%AE%88%E6%81%92%22%5D%0A%20%20I%20--%3E%20G%0A%20%20G%20--%3E%20CAP%5B%22throughput%20%E4%B8%8A%E9%99%90%E7%94%B1%E6%AD%A4%E9%94%81%E6%AD%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>远心破坏时，离焦相当于沿主光线走一段，像点跟着斜线走。频率语言里这不是低通半径变了，而是波前带上与视场相关的倾斜（一次项），与离焦二次相位叠加。后课写像差时，倾斜和离焦会进同一套光瞳相位；本课只需认出：远心是倾斜项的几何名字。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到 throughput，先问扩展量有没有匹配，再问源功率。说到通过焦点的套刻，先问像方远心，再问调平伺服。\\(\\sigma\\) 仍未正式作为填充比展开；本课只准备好「光瞳可以被填到多大」这一几何上限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>扩展量守恒假定无散射、无吸收。镀膜损耗、遮拦、积分棒墙壁都会吃光，但不改定义。本课不引用未公开的机台流明表或扫描速度。也不要把「远心镜头」理解成已经消像差：远心是主光线方向，球差、彗差仍在。</p><p>\\(\\mathrm{NA}\\) 截止频率的定义不改。后课部分相干用的照明孔径，必须落在本课扩展量允许的锥里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{NA}\\) 是张角；扩展量是面积×立体角，无损耗时守恒，限制 throughput。</li><li>源与投影必须匹配扩展量，否则填不满或喂过。</li><li>像方远心使离焦不改倍率；残余斜率让套刻随焦面漂。</li><li>远心不是焦深，也不是 \\(\\mathrm{NA}\\) 的别名。</li><li>照明填充比后面的课再写成 \\(\\sigma\\)。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Levinson, <em>Principles of Lithography</em>。</li></ul>',8))])}const _=s(p,[["render",d]]);export{N as __pageData,_ as default};
